#[allow(dependency_on_unit_never_type_fallback)]
pub fn create_app<R: tauri::Runtime>(builder: tauri::Builder<R>) -> tauri::Builder<R> {
    let pty_manager = Arc::new(PtyManager::new());
    let output_hub = Arc::new(TerminalOutputHub::default());
    let terminal_service = Arc::new(TerminalService::new(Arc::clone(&pty_manager), Arc::clone(&output_hub)));
    let workspace_registry = WorkspaceRegistry::new();
    let remote_state = Arc::new(RemoteGatewayState::new(Arc::clone(&terminal_service), workspace_registry.clone()));
    let remote_manager = Arc::new(RemoteGatewayManager::new(Arc::clone(&remote_state)));
    // Lazily initialized: a machine with no audio output device must still launch.
    let notification_audio = Arc::new(NotificationAudioPlayer::new());
    let browser_manager = Arc::new(browser::BrowserManager::new());

    if let Ok(repo_root) = std::env::current_dir() {
        if let Err(error) = workspace_registry.register("default", &repo_root) {
            tracing::debug!(
                "Current directory is not a registrable rorca workspace ({}): {}",
                repo_root.display(),
                error
            );
        }
    }

    builder
        .setup(|_app| {
            Ok(())
        })
        // Rust-side plugins only. The frontend uses rorca's own typed commands,
        // so no broad JavaScript guest capability needs to be granted.
        .plugin(tauri_plugin_notification::init())
        .plugin(tauri_plugin_dialog::init())
        .manage(pty_manager)
        .manage(output_hub)
        .manage(terminal_service)
        .manage(remote_manager)
        .manage(workspace_registry)
        .manage(notification_audio)
        .manage(browser_manager)
        .invoke_handler(tauri::generate_handler![
            cmd_terminal_spawn,
            cmd_terminal_write,
            cmd_terminal_resize,
            cmd_terminal_signal,
            cmd_terminal_close,
            cmd_terminal_list,
            cmd_terminal_preferences,
            cmd_remote_status,
            cmd_remote_enable,
            cmd_remote_disable,
            cmd_remote_pairing_create,
            cmd_remote_devices,
            cmd_remote_device_revoke,
            cmd_tailscale_status,
            cmd_project_register,
            cmd_project_branches,
            cmd_worktree_list,
            cmd_worktree_create,
            cmd_worktree_delete,
            cmd_worktree_delete_destructive,
            cmd_worktree_delete_preview,
            cmd_worktree_status,
            cmd_notification_dispatch,
            cmd_notification_get_permission_status,
            cmd_notification_request_permission,
            cmd_notification_probe_delivery,
            cmd_notification_open_system_settings,
            cmd_notification_play_sound,
            cmd_notification_pick_audio,
            cmd_session_save,
            cmd_session_load,
            cmd_session_clear,
            cmd_browser_create,
            cmd_browser_navigate,
            cmd_browser_reload,
            cmd_browser_set_bounds,
            cmd_browser_set_visible,
            cmd_browser_set_zoom,
            cmd_browser_focus,
            cmd_browser_get_state,
            cmd_browser_close,
            cmd_browser_list,
            cmd_browser_open_external,
        ])
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    create_app(tauri::Builder::default())
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

use crate::terminal::output_hub::TerminalOutputHub;
use crate::terminal::{PtyError, PtyManager, PtySession, TerminalSignal};
use crate::worktree::manager::WorktreeManager;
use portable_pty::CommandBuilder;
use std::path::Path;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Clone)]
pub struct TerminalService {
    pty_manager: Arc<PtyManager>,
    output_hub: Arc<TerminalOutputHub>,
}

impl Default for TerminalService {
    fn default() -> Self {
        Self::new(Arc::new(PtyManager::new()), Arc::new(TerminalOutputHub::default()))
    }
}

impl TerminalService {
    pub fn new(pty_manager: Arc<PtyManager>, output_hub: Arc<TerminalOutputHub>) -> Self {
        Self {
            pty_manager,
            output_hub,
        }
    }

    pub fn pty_manager(&self) -> &Arc<PtyManager> {
        &self.pty_manager
    }

    pub fn output_hub(&self) -> &Arc<TerminalOutputHub> {
        &self.output_hub
    }

    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, broadcast::Receiver<Vec<u8>>), PtyError> {
        let (session_id, mut pty_rx) = self
            .pty_manager
            .spawn_in_worktree(cmd, cols, rows, worktree_manager, worktree_path)?;

        let broadcast_rx = self.output_hub.register_session(&session_id);

        // Spawn output pump task from PTY reader to OutputHub
        let output_hub = Arc::clone(&self.output_hub);
        let session_id_clone = session_id.clone();
        tokio::spawn(async move {
            while let Some(chunk) = pty_rx.recv().await {
                output_hub.publish(&session_id_clone, chunk);
            }
        });

        Ok((session_id, broadcast_rx))
    }

    pub fn attach(&self, session_id: &str) -> Result<(Vec<u8>, broadcast::Receiver<Vec<u8>>), PtyError> {
        if !self.pty_manager.list_sessions().contains(&session_id.to_string()) {
            return Err(PtyError::SessionNotFound(session_id.to_string()));
        }

        self.output_hub
            .subscribe(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        self.pty_manager.write_input(session_id, data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        self.pty_manager.resize(session_id, cols, rows)
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        self.pty_manager.signal(session_id, signal)
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        self.output_hub.remove_session(session_id);
        self.pty_manager.close_session(session_id).await
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.pty_manager.list_sessions()
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.pty_manager.get_session(session_id)
    }
}

import type { WorkspaceState } from "../state/workspaceStore";
import type {
  PersistedLayout,
  PersistedTab,
  PersistedTerminalSession,
  PersistedWorkspace,
  PersistedWorkspaceSession,
  PersistedWorktree,
} from "./types";

export function serializeWorkspaceState(
  workspaceId: string,
  repoRoot: string,
  state: WorkspaceState,
): PersistedWorkspaceSession {
  const persistedWorktrees: PersistedWorktree[] = state.worktrees.map((wt) => ({
    path: wt.path,
    branch: wt.branch ?? "",
    head: wt.head,
    isMain: !wt.branch || wt.branch === "main" || wt.branch === "master",
    isLocked: Boolean(wt.locked),
  }));

  const persistedTabs: PersistedTab[] = state.layout.tabs.map((tab) => {
    const tabLayout = state.layout.layoutsByTabId[tab.id];
    const sessionId = tab.kind === "browser" ? tab.browserId : tab.sessionId;
    const worktreePath = tab.kind === "browser" ? "" : (state.sessions[tab.sessionId]?.cwd ?? "");
    return {
      id: tab.id,
      sessionId,
      label: tab.label,
      worktreePath,
      paneTree: tabLayout?.root,
      sessionIdsByLeafId: tabLayout?.sessionIdsByLeafId,
      activeLeafId: tabLayout?.activeLeafId,
    };
  });

  const persistedLayout: PersistedLayout = {
    splitMode: state.layout.split ?? "none",
    primaryTabId: state.layout.primaryTabId ?? null,
    secondaryTabId: state.layout.secondaryTabId ?? null,
    activeTabId: state.layout.activeTabId ?? null,
    tabs: persistedTabs,
  };

  const persistedTerminalSessions: Record<string, PersistedTerminalSession> = {};
  for (const [id, sess] of Object.entries(state.sessions)) {
    if (!sess) continue;
    persistedTerminalSessions[id] = {
      sessionId: sess.id,
      worktreePath: sess.cwd,
      cwd: sess.cwd,
      createdAt: Date.now(),
    };
  }

  const workspace: PersistedWorkspace = {
    workspaceId,
    repoRoot,
    worktrees: persistedWorktrees,
    activeWorktreePath: state.activeWorktreePath,
    layout: persistedLayout,
    terminalSessions: persistedTerminalSessions,
  };

  return {
    version: 1,
    timestamp: Date.now(),
    activeWorkspaceId: workspaceId,
    workspaces: {
      [workspaceId]: workspace,
    },
  };
}

use parking_lot::RwLock;
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use tokio::sync::broadcast;

const DEFAULT_BUFFER_CAPACITY: usize = 512 * 1024; // 512 KiB
const BROADCAST_CAPACITY: usize = 1024;

pub struct BoundedBuffer {
    capacity: usize,
    chunks: VecDeque<Vec<u8>>,
    current_size: usize,
}

impl BoundedBuffer {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            chunks: VecDeque::new(),
            current_size: 0,
        }
    }

    pub fn push(&mut self, chunk: Vec<u8>) {
        if chunk.is_empty() {
            return;
        }
        self.current_size += chunk.len();
        self.chunks.push_back(chunk);

        while self.current_size > self.capacity && !self.chunks.is_empty() {
            if let Some(front) = self.chunks.pop_front() {
                self.current_size -= front.len();
            }
        }
    }

    pub fn snapshot(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.current_size);
        for chunk in &self.chunks {
            out.extend_from_slice(chunk);
        }
        out
    }
}

struct SessionHub {
    buffer: BoundedBuffer,
    sender: broadcast::Sender<Vec<u8>>,
}

#[derive(Clone)]
pub struct TerminalOutputHub {
    sessions: Arc<RwLock<HashMap<String, Arc<RwLock<SessionHub>>>>>,
    capacity: usize,
}

impl Default for TerminalOutputHub {
    fn default() -> Self {
        Self::new(DEFAULT_BUFFER_CAPACITY)
    }
}

impl TerminalOutputHub {
    pub fn new(capacity: usize) -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            capacity,
        }
    }

    pub fn register_session(&self, session_id: &str) -> broadcast::Receiver<Vec<u8>> {
        let (tx, rx) = broadcast::channel(BROADCAST_CAPACITY);
        let hub = SessionHub {
            buffer: BoundedBuffer::new(self.capacity),
            sender: tx,
        };
        self.sessions
            .write()
            .insert(session_id.to_string(), Arc::new(RwLock::new(hub)));
        rx
    }

    pub fn publish(&self, session_id: &str, chunk: Vec<u8>) {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        };

        if let Some(hub) = session_hub {
            let mut hub = hub.write();
            hub.buffer.push(chunk.clone());
            // It is okay if there are no active receivers; send returns Err in that case
            let _ = hub.sender.send(chunk);
        }
    }

    pub fn subscribe(&self, session_id: &str) -> Option<(Vec<u8>, broadcast::Receiver<Vec<u8>>)> {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        }?;

        let hub = session_hub.read();
        let history = hub.buffer.snapshot();
        let rx = hub.sender.subscribe();
        Some((history, rx))
    }

    pub fn remove_session(&self, session_id: &str) {
        self.sessions.write().remove(session_id);
    }

    pub fn has_session(&self, session_id: &str) -> bool {
        self.sessions.read().contains_key(session_id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_output_hub_replay_and_broadcast() {
        let hub = TerminalOutputHub::new(1024);
        let session_id = "test-session";
        let _initial_rx = hub.register_session(session_id);

        hub.publish(session_id, b"hello ".to_vec());
        hub.publish(session_id, b"world\n".to_vec());

        let (history, mut rx) = hub.subscribe(session_id).expect("session exists");
        assert_eq!(history, b"hello world\n");

        hub.publish(session_id, b"live chunk".to_vec());
        let received = rx.recv().await.expect("received live message");
        assert_eq!(received, b"live chunk");
    }

    #[tokio::test]
    async fn test_bounded_buffer_overflow() {
        let mut buffer = BoundedBuffer::new(10);
        buffer.push(b"12345".to_vec());
        buffer.push(b"67890".to_vec());
        buffer.push(b"abcdef".to_vec());

        let snap = buffer.snapshot();
        assert!(snap.len() <= 16); // pops chunks until under capacity
        assert!(snap.ends_with(b"abcdef"));
    }
}

